/// <summary>
/// This is a contract class
/// CB355_DutyRollMonthly
/// </summary>
[
    DataContractAttribute,
    SysOperationContractProcessingAttribute(classStr(METDutyRollMonthlyUIBuilder))
]
class METDutyRollMonthlyContract extends METSysOperationTaskDataContract
{
    List        itemList = new List (Types::String);
    List        siteList = new List (Types::String);
    boolean     adHoc;
    boolean     runForExcise;
    boolean     immediateChange;
    TransDate   startDate;
    int         tasksNumber;
    boolean     businessEventTask;
    container   conItems;
    private TransDate effectiveDate;
    private boolean cpi;

}

