    /// <summary>
    /// Validates data contract.
    /// </summary>
    /// <returns>True, if validated; otherwise, false.</returns>
    public boolean validate()
    {
        boolean ret = true;

        // Effective Date is mandatory
        if (!effectiveDate)
        {
            ret = checkFailed("@MET:EffectiveDatemandatory");
        }

        return ret;
    }
